import numpy as np


def _find_slots(grid):
    """Find the four bottom slots (rows 57-60) and their center columns."""
    # Slots are at rows 57-60, each 4 wide, separated by 4-wide gaps of color 4
    # From initial grid: slot centers at cols 19.5, 27.5, 35.5, 43.5
    # Slot left edges: 18, 26, 34, 42
    return [(57, 18), (57, 26), (57, 34), (57, 42)]


def _get_slot_color(grid, r, c):
    """Get the dominant non-4 color in a slot region (r..r+3, c..c+3)."""
    colors = []
    for dr in range(4):
        for dc in range(4):
            v = int(grid[r + dr][c + dc])
            if v != 4:
                colors.append(v)
    if not colors:
        return None
    from collections import Counter
    cnt = Counter(colors)
    return cnt.most_common(1)[0][0]


def engine(grid, action, data):
    g = grid.copy()

    if action == 6 and data is not None:
        px, py = data['x'], data['y']
        col, row = px, py  # pixel = logical * 1

        # Check if clicking on a bottom slot (rows 57-60)
        slots = _find_slots(g)
        clicked_slot = None
        for sr, sc in slots:
            if sr <= row < sr + 4 and sc <= col < sc + 4:
                clicked_slot = (sr, sc)
                break

        if clicked_slot is not None:
            sr, sc = clicked_slot
            current_color = _get_slot_color(g, sr, sc)

            if current_color is None or current_color == 4:
                # Empty slot: fill with color 0 (black)
                for dr in range(4):
                    for dc in range(4):
                        g[sr + dr][sc + dc] = 0
            else:
                # Filled slot: clear it back to 4
                for dr in range(4):
                    for dc in range(4):
                        g[sr + dr][sc + dc] = 4

            # Also handle the border rows above/below the slot area
            # Row 56 (above) and row 61 (below) have 6-wide spans at slot positions
            # These are the "caps" of the slots
            cap_cols = [17, 25, 33, 41]
            for cc in cap_cols:
                pass  # caps change together with slot content

            # Update caps based on new state
            # Determine which slot index was clicked
            slot_idx = None
            for i, (sr2, sc2) in enumerate(slots):
                if sr2 == sr and sc2 == sc:
                    slot_idx = i
                    break

            if slot_idx is not None:
                cap_c = cap_cols[slot_idx]
                # If we just filled (was empty -> now 0), set caps to 0
                # If we just cleared (was colored -> now 4), set caps to 4
                if current_color is None or current_color == 4:
                    g[56][cap_c:cap_c + 6] = 0
                    g[61][cap_c:cap_c + 6] = 0
                else:
                    g[56][cap_c:cap_c + 6] = 4
                    g[61][cap_c:cap_c + 6] = 4

        # Check if clicking on the top display area (rows 1-6, cols 18-44)
        elif 1 <= row <= 6 and 18 <= col <= 44:
            # This might toggle something but observed no change for some clicks
            pass

    return g


def is_level_complete(grid):
    """Check if all four bottom slots are filled with matching colors."""
    slots = _find_slots(grid)
    expected_colors = [14, 15, 9, 11]  # from initial grid layout

    for i, (sr, sc) in enumerate(slots):
        color = _get_slot_color(grid, sr, sc)
        if color != expected_colors[i]:
            return False
    return True
